svg.script:
for (const coin of document.querySelectorAll('.coin')) {
  const flip = () => {
    const back = coin.classList.contains('to-back');
    coin.classList.toggle('to-back', !back);
    coin.classList.toggle('to-front', back);
    coin.setAttribute('aria-pressed', String(!back));
  };
  coin.addEventListener('click', flip);
  coin.addEventListener('keydown', (e) => {
    if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); flip(); }
  });
}
